  local curr = n _ ""
  while (curr !== "6174") {
    while (curr.textLen() < 4) { curr = "0" _ curr }
    local digits =[]
    for (i: 1 .. 4) { digits.add(curr.segment(i, 1)) }
    local asc = digits.sort { a, b -> a << b }.join("")
    local desc = digits.sort { a, b -> a >> b }.join("")
    curr = (asc + 0 > desc + 0 ? asc + 0 - (desc + 0) : desc + 0 - (asc + 0)) _ ""
    steps = steps + 1
  }
  steps
}
